record.field:
{
            "page": {"footer_text": "Confidential -- Offer Letter"},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Offer Letter", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "Dear {{ candidate_name }},\nWe are pleased to offer you the position of {{ position }}."}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 30, "z": 1, "props": {"text": "Start Date: {{ start_date }}\nAnnual Salary: {{ annual_salary }}"}},
                {"id": "b4", "type": "text", "x": 40, "y": 180, "w": 420, "h": 24, "z": 1, "props": {"text": "Reporting Manager: {{ reporting_manager }}"}},
                {"id": "b5", "type": "signature", "x": 40, "y": 220, "w": 200, "h": 60, "z": 1, "props": {"label": "Candidate Signature"}},
                {"id": "b6", "type": "signature", "x": 260, "y": 220, "w": 200, "h": 60, "z": 1, "props": {"label": "HR Signature"}}
            ]
        }

{
            "page": {"footer_text": "Confidential -- Employment Contract"},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Employment Contract", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "Employee: {{ employee_name }}\nPosition: {{ position }}"}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 30, "z": 1, "props": {"text": "Start Date: {{ start_date }}\nAnnual Salary: {{ salary }}"}},
                {"id": "b4", "type": "signature", "x": 40, "y": 200, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}},
                {"id": "b5", "type": "signature", "x": 260, "y": 200, "w": 200, "h": 60, "z": 1, "props": {"label": "HR Signature"}}
            ]
        }

{
            "page": {"footer_text": "Confidential -- Non-Disclosure Agreement"},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Non-Disclosure Agreement", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "This agreement is between {{ company_name }} and {{ employee_name }}, effective {{ effective_date }}."}},
                {"id": "b3", "type": "signature", "x": 40, "y": 150, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}},
                {"id": "b4", "type": "signature", "x": 260, "y": 150, "w": 200, "h": 60, "z": 1, "props": {"label": "Company Signature"}}
            ]
        }

{
            "page": {},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Policy Acknowledgment", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "I, {{ employee_name }}, acknowledge that I have read and understood the policy: {{ policy_name }}."}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 24, "z": 1, "props": {"text": "Date: {{ acknowledgment_date }}"}},
                {"id": "b4", "type": "signature", "x": 40, "y": 180, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}}
            ]
        }

{
            "page": {},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Appraisal Form", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "Employee: {{ employee_name }}\nReview Period: {{ review_period }}"}},
                {"id": "b3", "type": "table", "x": 40, "y": 140, "w": 320, "h": 50, "z": 1, "props": {"headers": ["Reviewer", "Overall Rating"], "rows": [["{{ reviewer_name }}", "{{ overall_rating }}"]]}},
                {"id": "b4", "type": "signature", "x": 40, "y": 210, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}},
                {"id": "b5", "type": "signature", "x": 260, "y": 210, "w": 200, "h": 60, "z": 1, "props": {"label": "Reviewer Signature"}}
            ]
        }

{
            "page": {},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Relieving Letter", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "This is to certify that {{ employee_name }}, {{ designation }}, was relieved of duties.\nLast Working Day: {{ last_working_day }}"}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 24, "z": 1, "props": {"text": "Relieving Date: {{ relieving_date }}"}},
                {"id": "b4", "type": "divider", "x": 40, "y": 170, "w": 420, "h": 2, "z": 1, "props": {}},
                {"id": "b5", "type": "signature", "x": 40, "y": 190, "w": 200, "h": 60, "z": 1, "props": {"label": "HR Signature"}}
            ]
        }

{
            "page": {},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Warning Letter", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "Dear {{ employee_name }},\nThis letter serves as a formal warning regarding: {{ issue_description }}"}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 24, "z": 1, "props": {"text": "Date: {{ issue_date }}"}},
                {"id": "b4", "type": "signature", "x": 40, "y": 180, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}},
                {"id": "b5", "type": "signature", "x": 260, "y": 180, "w": 200, "h": 60, "z": 1, "props": {"label": "HR Signature"}}
            ]
        }

{
            "page": {},
            "blocks": [
                {"id": "b1", "type": "heading", "x": 40, "y": 40, "w": 420, "h": 34, "z": 1, "props": {"text": "Promotion / Increment Letter", "level": 1}},
                {"id": "b2", "type": "text", "x": 40, "y": 90, "w": 420, "h": 44, "z": 1, "props": {"text": "Dear {{ employee_name }},\nWe are pleased to confirm your promotion to {{ new_position }}."}},
                {"id": "b3", "type": "text", "x": 40, "y": 140, "w": 420, "h": 30, "z": 1, "props": {"text": "New Annual Salary: {{ new_salary }}\nEffective Date: {{ effective_date }}"}},
                {"id": "b4", "type": "signature", "x": 40, "y": 190, "w": 200, "h": 60, "z": 1, "props": {"label": "Employee Signature"}},
                {"id": "b5", "type": "signature", "x": 260, "y": 190, "w": 200, "h": 60, "z": 1, "props": {"label": "HR Signature"}}
            ]
        }
